// Client REST API contract (issue #649). Mirrors the Go types in
// internal/client/sdk/shared/types.go; every route lives under
// /api/v1/client (see CONTRACTS.md). Frozen: units do not edit this file;
// unit-specific types go in types/client/<unit>.ts.

// ------------------------------------------------------------------ common

export type ISODate = string;

/** Body of every client API error. */
export interface ClientApiError {
  error: string;
  /** Stable code: not_implemented, not_found, not_connected, name_taken,
   * invalid, server_unreachable, server_auth, unavailable, ... */
  code?: string;
  field?: string;
}

// ---------------------------------------------------------------- manifest
// Manifest, spec, lock and diff shapes are internal/artifact's JSON types
// (CONTRACTS-artifact.md), served as is by the client API.

export type PackageSource = 'conda' | 'pypi';

/** Constraint is a match spec: ">=2.0", "3.11.*" or "*" (any). */
export interface RequestedPackage {
  name: string;
  constraint: string;
  /** Omitted or "conda" for conda packages, "pypi" for PyPI. */
  source?: PackageSource;
}

/** GUI form view of a pixi.toml. description is pixi's optional
 * [workspace] description, not the Nebi version description. */
export interface ManifestForm {
  name: string;
  description?: string;
  channels: string[];
  platforms: string[];
  requested: RequestedPackage[];
}

/** POST /client/manifest/parse. unrepresentable lists what the form
 * cannot show, e.g. "[tasks]", "workspace.authors". */
export interface ManifestParseResult {
  form: ManifestForm;
  unrepresentable: string[];
}

/** POST /client/manifest/render. With base_pixi_toml the form is applied
 * onto it, keeping everything the form cannot show. */
export interface ManifestRenderRequest {
  form: ManifestForm;
  base_pixi_toml?: string;
}

export interface ManifestRenderResult {
  pixi_toml: string;
}

/** Version operators of the package form (prototype order). */
export const VERSION_OPERATORS = [
  ['none', 'the version as written'],
  ['>=', 'at least'],
  ['==', 'exactly'],
  ['<=', 'at most'],
  ['>', 'newer than'],
  ['<', 'older than'],
  ['!=', 'anything but'],
  ['~=', 'compatible with'],
] as const;

// ---------------------------------------------------------------- projects

export type ProjectStatus =
  | 'pending'
  | 'creating'
  | 'ready'
  | 'failed'
  | 'deleting';

export type InstallStatus =
  | 'not_installed'
  | 'installing'
  | 'installed'
  | 'uninstalling'
  | 'install_failed';

export type RemoteKind = 'server' | 'registry';

export interface RemoteRef {
  kind: RemoteKind;
  /** Display label, e.g. "team-nebi" or "ghcr.io/example-org". */
  name: string;
  url?: string;
  server_project_id?: string;
}

/** GET /client/projects item and the project detail header. */
export interface ProjectListItem {
  id: string;
  name: string;
  path: string;
  status: ProjectStatus;
  install_status: InstallStatus;
  installed_version: number | null;
  last_installed_version: number | null;
  latest_version: number | null;
  size_bytes: number | null;
  /** Formatted size ("1.2 GB"); "" when unknown. */
  size: string;
  remotes: RemoteRef[];
  update_available: boolean;
  server_latest_version: number | null;
  failed_install_job_id: string | null;
  active_job_id: string | null;
  created_at: ISODate;
  updated_at: ISODate;
}

/** POST /client/projects. Exactly one of pixi_toml or form. */
export interface CreateProjectRequest {
  name: string;
  path?: string;
  pixi_toml?: string;
  form?: ManifestForm;
  description?: string;
  tags?: string[];
  install?: boolean;
}

export interface CreateProjectResult {
  project: ProjectListItem;
  job: JobSummary;
}

export interface NameCheckResult {
  name: string;
  available: boolean;
  error?: string;
}

// ---------------------------------------------------------------- versions

export interface Author {
  name: string;
  username?: string;
}

export interface PublishedRef {
  publication_id: string | null;
  registry_id: string | null;
  registry: string;
  repository: string;
  tag: string;
  /** registry/repository:tag */
  reference: string;
  source: 'local' | 'server';
  can_unpublish: boolean;
}

export type SyncMarker = 'newest_here' | 'newest_on_server' | 'in_sync';

export const SYNC_MARKER_LABELS: Record<SyncMarker, string> = {
  newest_here: 'Newest here',
  newest_on_server: 'Newest on server',
  in_sync: 'In sync',
};

/** Version rail row. Server-only versions have server_only = true. */
export interface VersionItem {
  number: number;
  description: string;
  author: Author;
  created_at: ISODate;
  /** Never contains content-hash tags; "latest" is on the newest version. */
  tags: string[];
  base_version: number | null;
  published: PublishedRef[];
  sync: SyncMarker | null;
  server_only: boolean;
  installed: boolean;
  content_hash?: string;
}

export interface EnvironmentSpec {
  channels: string[];
  platforms: string[];
  requested: RequestedPackage[];
}

export interface VersionDetail extends VersionItem {
  spec: EnvironmentSpec;
}

export interface FileContent {
  name: 'pixi.toml' | 'pixi.lock' | string;
  content: string;
}

/** artifact.ResolvedPackage. size is bytes (0 when unknown, always 0 for PyPI). */
export interface ResolvedPackage {
  name: string;
  version: string;
  build?: string;
  source: PackageSource;
  platform: string;
  /** Short name (conda-forge) or base URL; "pypi" for PyPI. */
  channel: string;
  channel_url?: string;
  url?: string;
  size: number;
}

export interface ResolvedPackages {
  platforms: string[];
  packages: Record<string, ResolvedPackage[]>;
  total_size: Record<string, number>;
}

/** POST /client/projects/:id/install. No version = last installed, else latest. */
export interface InstallRequest {
  version?: number;
}

/** POST /client/projects/:id/versions. */
export interface CreateVersionRequest {
  base_version: number;
  pixi_toml?: string;
  form?: ManifestForm;
  description: string;
  tags?: string[];
}

// ----------------------------------------------------------------- compare

export type PackageChangeKind = 'same' | 'added' | 'removed' | 'changed';

export interface PackageRef {
  constraint?: string;
  version: string;
  build?: string;
  channel?: string;
}

/** One compare row; base is null when added, compare null when removed. */
export interface PackageDiffEntry {
  name: string;
  source: PackageSource;
  change: PackageChangeKind;
  base: PackageRef | null;
  compare: PackageRef | null;
}

export interface DiffCounts {
  added: number;
  removed: number;
  changed: number;
  same: number;
}

export interface ListDiff {
  added: string[] | null;
  removed: string[] | null;
}

/** artifact.VersionDiff: Compare versions and "Summary of changes". */
export interface VersionDiff {
  platform: string;
  requested: PackageDiffEntry[];
  requested_counts: DiffCounts;
  resolved: PackageDiffEntry[];
  resolved_counts: DiffCounts;
  channels: ListDiff;
  platforms: ListDiff;
}

export interface CompareVersionRef {
  number: number;
  server_only: boolean;
  installed: boolean;
  server_latest: boolean;
}

/** GET /client/projects/:id/compare?base=&target= */
export interface CompareResult extends VersionDiff {
  base: CompareVersionRef;
  target: CompareVersionRef;
}

// ------------------------------------------------------------------ remote

export type ServerAuth = 'none' | 'token';

export interface ServerConnection {
  connected: boolean;
  url: string;
  name: string;
  /** "Signed in as" */
  username: string;
  auth: ServerAuth;
  last_synced_at: ISODate | null;
}

export interface ConnectRequest {
  url: string;
  auth: ServerAuth;
  token?: string;
}

export type ShareRole = 'owner' | 'edit' | 'view';

export const SHARE_ROLE_LABELS: Record<ShareRole, string> = {
  owner: 'Owner',
  edit: 'Can edit',
  view: 'Can view',
};

export interface ServerProjectItem {
  id: string;
  name: string;
  owner: string;
  /** "Personal" or a team name. */
  namespace: string;
  latest_version: number | null;
  updated_at: ISODate | null;
  role: ShareRole;
  local_project_id: string | null;
}

export interface ServerProjectList {
  projects: ServerProjectItem[];
  last_synced_at: ISODate | null;
}

/** POST /client/remote/projects/:serverProjectId/pull. 409 code name_taken. */
export interface PullRequest {
  local_name: string;
  path?: string;
  install: boolean;
}

export interface PullResult {
  project_id: string;
  job: JobSummary;
}

export interface PushResult {
  pushed_versions: number[];
  server_latest_version: number;
  server_project_id: string;
}

export interface RemoteDetails {
  project: ServerProjectItem;
  url: string;
  versions: VersionItem[];
}

// ----------------------------------------------------------------- sharing

export interface Principal {
  kind: 'user' | 'group';
  id: string;
  name: string;
  email?: string;
  members?: number;
}

export interface AccessEntry {
  principal: Principal;
  role: ShareRole;
}

export interface AccessList {
  entries: AccessEntry[];
  can_manage: boolean;
}

export interface PrincipalRef {
  kind: 'user' | 'group';
  id: string;
}

export interface GrantAccessRequest {
  principals: PrincipalRef[];
  role: Exclude<ShareRole, 'owner'>;
}

export interface UpdateAccessRequest {
  role: Exclude<ShareRole, 'owner'>;
}

// ---------------------------------------------------------------- registry

export interface RegistryItem {
  id: string;
  name: string;
  url: string;
  namespace: string;
  username: string;
  has_credentials: boolean;
  is_default: boolean;
  can_unpublish: boolean;
  unpublish_reason?: string;
}

export interface AddRegistryRequest {
  name: string;
  url: string;
  namespace?: string;
  username?: string;
  password?: string;
  is_default?: boolean;
}

export interface PublishTarget {
  registry_id: string;
  repository: string;
  tag: string;
}

export interface PublishRequest {
  targets: PublishTarget[];
}

export interface PublishDefault {
  registry_id: string;
  registry_name: string;
  repository: string;
  tag: string;
}

export interface PublishResultItem {
  registry_id: string;
  registry_name: string;
  reference: string;
  status: 'published' | 'failed';
  error?: string;
  digest?: string;
  publication_id: string | null;
}

export interface PublishResult {
  results: PublishResultItem[];
}

export interface RegistryPullRequest {
  repository: string;
  tag: string;
  local_name: string;
  install: boolean;
}

// -------------------------------------------------------------------- jobs

export type JobType =
  | 'create'
  | 'delete'
  | 'create_version'
  | 'install_version'
  | 'uninstall'
  | 'pull'
  | 'pull_install'
  | 'pull_registry'
  | 'install'
  | 'remove'
  | 'update'
  | 'rollback'
  | 'env_install'
  | 'env_uninstall';

/** Keep in sync with models.JobTypeLabels (internal/models/job.go). */
export const JOB_TYPE_LABELS: Record<JobType, string> = {
  create: 'Create project',
  delete: 'Delete project',
  create_version: 'Create version',
  install_version: 'Install version',
  uninstall: 'Uninstall',
  pull: 'Pull project',
  pull_install: 'Pull and install',
  pull_registry: 'Pull from registry',
  install: 'Add packages',
  remove: 'Remove packages',
  update: 'Update project',
  rollback: 'Rollback',
  env_install: 'Install environment',
  env_uninstall: 'Uninstall environment',
};

/** Job types the version model creates (Jobs page type filter). */
export const VERSION_MODEL_JOB_TYPES: JobType[] = [
  'create',
  'create_version',
  'install_version',
  'uninstall',
  'pull',
  'pull_install',
  'pull_registry',
  'delete',
];

export type JobStatus =
  | 'pending'
  | 'running'
  | 'completed'
  | 'failed'
  | 'cancelled';

/** UI labels (prototype: Queued / Running / Succeeded / Failed / Cancelled). */
export const JOB_STATUS_LABELS: Record<JobStatus, string> = {
  pending: 'Queued',
  running: 'Running',
  completed: 'Succeeded',
  failed: 'Failed',
  cancelled: 'Cancelled',
};

export const isActiveJob = (job: Pick<JobSummary, 'status'>) =>
  job.status === 'pending' || job.status === 'running';

export interface JobSummary {
  id: string;
  type: JobType;
  type_label: string;
  status: JobStatus;
  project_id: string;
  project_name: string;
  version_number: number | null;
  created_at: ISODate;
  started_at: ISODate | null;
  completed_at: ISODate | null;
  duration_ms: number | null;
  error?: string;
}

export interface JobDetail extends JobSummary {
  logs: string;
}

/** GET /client/jobs query. Arrays are sent comma-separated. */
export interface JobListFilter {
  status?: JobStatus[];
  type?: JobType[];
  project_id?: string;
  sort?: 'started_at' | '-started_at';
  limit?: number;
}

// ------------------------------------------------------------ capabilities

export interface Capabilities {
  native_folder_picker: boolean;
  platform: string;
  default_projects_dir: string;
}

export interface PickFolderRequest {
  title?: string;
  default_path?: string;
}

export interface PickFolderResult {
  path: string;
  cancelled: boolean;
}
